import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.Cp9o0o35.js";const m=JSON.parse('{"title":"Compare three types","description":"","frontmatter":{},"headers":[],"relativePath":"en/compare.md","filePath":"en/compare.md"}'),s={name:"en/compare.md"};function i(n,e,h,p,l,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="compare-three-types" tabindex="-1">Compare three types <a class="header-anchor" href="#compare-three-types" aria-label="Permalink to &quot;Compare three types&quot;">​</a></h1><p>bridge-lite treats the camera JPEG, RAW, and developed file from the same shutter press as <strong>one group</strong>.</p><h2 id="why-compare-all-three" tabindex="-1">Why compare all three <a class="header-anchor" href="#why-compare-all-three" aria-label="Permalink to &quot;Why compare all three&quot;">​</a></h2><p>Sometimes the camera&#39;s output is simply better. Sometimes heavy processing makes you lose track of the original. Switching between all three gives you a clear ground truth before you decide which to keep.</p><h2 id="switching-between-variants" tabindex="-1">Switching between variants <a class="header-anchor" href="#switching-between-variants" aria-label="Permalink to &quot;Switching between variants&quot;">​</a></h2><p>With a photo selected, press <code>Tab</code> to cycle through the files in its group:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Camera JPEG → RAW → Developed → Camera JPEG → …</span></span></code></pre></div><h2 id="how-pairing-works" tabindex="-1">How pairing works <a class="header-anchor" href="#how-pairing-works" aria-label="Permalink to &quot;How pairing works&quot;">​</a></h2><p>RAW and JPG files are automatically paired in this order:</p><ol><li><strong>Stem name</strong> — <code>DSC04867.ARW</code> and <code>DSC04867.JPG</code> share the same stem</li><li><strong>EXIF timestamp</strong> — Files shot at the same time, even with different names</li><li><strong>pHash</strong> — Perceptual hash for visual similarity</li></ol><h2 id="group-compare-view" tabindex="-1">Group compare view <a class="header-anchor" href="#group-compare-view" aria-label="Permalink to &quot;Group compare view&quot;">​</a></h2><p>Press <code>G</code> to open the group compare view, which displays all variants side by side on screen.</p><h2 id="what-counts-as-developed" tabindex="-1">What counts as &quot;developed&quot; <a class="header-anchor" href="#what-counts-as-developed" aria-label="Permalink to &quot;What counts as &quot;developed&quot;&quot;">​</a></h2><p>A JPEG or TIFF exported from Lightroom (or any editor) with the same stem name in the same folder is automatically recognized as a developed variant.</p>',14)])])}const u=a(s,[["render",i]]);export{m as __pageData,u as default};
